			BestFrame = Slots[i].FrameNumber;
			BestSlot = i;
		}
	}

	if (BestSlot < 0)
	{
		return false;
	}

	const FFrameSlot& Slot = Slots[BestSlot];
	OutPixels = Slot.Pixels;
	OutSize = Slot.Size;
	OutMetadata = Slot.Metadata;
	OutFrameNumber = Slot.FrameNumber;
	OutTimestamp = Slot.Timestamp;
	return true;
}

