class Colors:
    CYAN = '\033[96m'
    GREEN = '\033[92m'
    YELLOW = '\033[93m'
    RED = '\033[91m'
    DIM = '\033[90m'
    RESET = '\033[0m'
    BOLD = '\033[1m'

def clear_screen():
    try:
        import os
        if sys.stdout.isatty():
            os.system('cls' if os.name == 'nt' else 'clear')
        else:
            print("\n" + "=" * 60 + "\n")
    except Exception:
        pass

def print_banner():
    clear_screen()
    print(f"""
{Colors.CYAN}  +-----------------------------------------------------------+
  |                                                           |
  |   {Colors.BOLD}THE TRANSLATORS{Colors.RESET}{Colors.CYAN} -- Cognitive Profile Orchestrator       |
  |                                                           |
