{Colors.BOLD}  Question {index + 1} of {total}{Colors.RESET}
{Colors.DIM}  Scene: {q['scene']}{Colors.RESET}

{Colors.CYAN}  {q['text'].replace(chr(10), chr(10) + '  ')}{Colors.RESET}

