   1→// BridgeComponent.cpp
   2→// Claude Code → UE5.7 File-Based Bridge Implementation
   3→// v2.0.0: USD-native communication with JSON fallback
   4→
   5→#include "BridgeComponent.h"
   6→#include "Misc/FileHelper.h"
   7→#include "Misc/Paths.h"
   8→#include "HAL/PlatformProcess.h"
   9→#include "HAL/PlatformFileManager.h"
  10→#include "JsonObjectConverter.h"
  11→#include "Serialization/JsonReader.h"
  12→#include "Serialization/JsonWriter.h"
  13→#include "Serialization/JsonSerializer.h"
  14→#include "Internationalization/Regex.h"
  15→
  16→// Directory watcher (editor-only)
  17→#if WITH_DIRECTORY_WATCHER
  18→#include "DirectoryWatcherModule.h"
  19→#include "IDirectoryWatcher.h"
  20→#endif
  21→
  22→
  23→UBridgeComponent::UBridgeComponent()
  24→{
  25→    PrimaryComponentTick.bCanEverTick = true;
  26→
  27→    // Resolve home directory reliably on Windows
  28→    // FPlatformProcess::UserHomeDir() can return Documents folder on some configs
  29→    FString HomePath;
  30→
  31→#if PLATFORM_WINDOWS
  32→    // Use USERPROFILE env var directly (most reliable on Windows)
  33→    FString UserProfile = FPlatformMisc::GetEnvironmentVariable(TEXT("USERPROFILE"));
  34→    if (!UserProfile.IsEmpty())
  35→    {
  36→        HomePath = UserProfile;
  37→    }
  38→    else
  39→    {
  40→        HomePath = FPlatformProcess::UserHomeDir();
  41→    }
  42→#else
  43→    HomePath = FPlatformProcess::UserHomeDir();
  44→#endif
  45→
  46→    // Clean up path separators and trailing slashes
  47→    FPaths::NormalizeDirectoryName(HomePath);
  48→
  49→    BridgePath = FPaths::Combine(HomePath, TEXT(".translators"));
  50→}
  51→
  52→
  53→void UBridgeComponent::BeginPlay()
  54→{
  55→    Super::BeginPlay();
  56→
  57→    BridgeLog(TEXT("========================================"));
  58→    BridgeLog(TEXT("TRANSLATORS BRIDGE COMPONENT v2.0.0"));
  59→    BridgeLog(TEXT("USD-native communication with JSON fallback"));
  60→    BridgeLog(FString::Printf(TEXT("Bridge Path: %s"), *BridgePath));
  61→    BridgeLog(FString::Printf(TEXT("Resolved state.json: %s"), *GetBridgeFilePath(TEXT("state.json"))));
  62→    BridgeLog(TEXT("========================================"));
  63→
  64→    // Ensure bridge directory exists
  65→    IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
  66→    if (!PlatformFile.DirectoryExists(*BridgePath))
  67→    {
  68→        PlatformFile.CreateDirectory(*BridgePath);
  69→        BridgeLog(FString::Printf(TEXT("Created bridge directory: %s"), *BridgePath));
  70→    }
  71→
  72→    SetupFileWatcher();
  73→
  74→    // Check for existing state files (Claude Code may have started first)
  75→    // Prefer USD over JSON
  76→    FString UsdFilePath = GetBridgeFilePath(TEXT("bridge_state.usda"));
  77→    FString JsonFilePath = GetBridgeFilePath(TEXT("state.json"));
  78→
  79→    if (PlatformFile.FileExists(*UsdFilePath))
  80→    {
  81→        BridgeLog(TEXT("Found existing bridge_state.usda - processing..."));
  82→        ProcessStateFile();
  83→    }
  84→    else if (PlatformFile.FileExists(*JsonFilePath))
  85→    {
  86→        BridgeLog(TEXT("Found existing state.json - processing..."));
  87→        ProcessStateFile();
  88→    }
  89→}
  90→
  91→
  92→void UBridgeComponent::EndPlay(const EEndPlayReason::Type EndPlayReason)
  93→{
  94→    TeardownFileWatcher();
  95→
  96→    BridgeLog(TEXT("TRANSLATORS BRIDGE COMPONENT STOPPED"));
  97→
  98→    Super::EndPlay(EndPlayReason);
  99→}
 100→
 101→
 102→void UBridgeComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
 103→{
 104→    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);
 105→
 106→    // Polling fallback for non-editor builds
 107→    if (bUsePolling)
 108→    {
 109→        PollTimer += DeltaTime;
 110→        if (PollTimer >= PollInterval)
 111→        {
 112→            PollTimer = 0.0f;
 113→
 114→            FString StateFilePath = GetBridgeFilePath(TEXT("state.json"));
 115→            IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
 116→
 117→            if (PlatformFile.FileExists(*StateFilePath))
 118→            {
 119→                FDateTime ModTime = PlatformFile.GetTimeStamp(*StateFilePath);
 120→                if (ModTime > LastStateFileTime)
 121→                {
 122→                    LastStateFileTime = ModTime;
 123→                    bStateChangePending = true;
 124→                    TimeSinceLastStateChange = 0.0f;
 125→                }
 126→            }
 127→        }
 128→    }
 129→
 130→    // Debounced state file processing
 131→    if (bStateChangePending)
 132→    {
 133→        TimeSinceLastStateChange += DeltaTime;
 134→        if (TimeSinceLastStateChange >= DebounceTime)
 135→        {
 136→            bStateChangePending = false;
 137→            ProcessStateFile();
 138→        }
 139→    }
 140→
 141→    // Debounced USD file processing
 142→    if (bUsdChangePending)
 143→    {
 144→        TimeSinceLastUsdChange += DeltaTime;
 145→        if (TimeSinceLastUsdChange >= DebounceTime)
 146→        {
 147→            bUsdChangePending = false;
 148→            OnUsdFileChanged();
 149→        }
 150→    }
 151→}
 152→
 153→
 154→// === FILE WATCHING ===
 155→
 156→void UBridgeComponent::SetupFileWatcher()
 157→{
 158→#if WITH_DIRECTORY_WATCHER
 159→    FDirectoryWatcherModule& DirWatcherModule =
 160→        FModuleManager::LoadModuleChecked<FDirectoryWatcherModule>(TEXT("DirectoryWatcher"));
 161→    IDirectoryWatcher* DirWatcher = DirWatcherModule.Get();
 162→
 163→    if (!DirWatcher)
 164→    {
 165→        BridgeLog(TEXT("ERROR: Could not get DirectoryWatcher module"));
 166→        return;
 167→    }
 168→
 169→    IDirectoryWatcher::FDirectoryChanged Callback =
 170→        IDirectoryWatcher::FDirectoryChanged::CreateUObject(
 171→            this, &UBridgeComponent::OnDirectoryChanged);
 172→
 173→    uint32 WatchFlags = 0; // No special flags needed
 174→
 175→    bool bSuccess = DirWatcher->RegisterDirectoryChangedCallback_Handle(
 176→        BridgePath, Callback, WatchHandle, WatchFlags);
 177→
 178→    if (bSuccess)
 179→    {
 180→        BridgeLog(FString::Printf(TEXT("File watcher registered for: %s"), *BridgePath));
 181→    }
 182→    else
 183→    {
 184→        BridgeLog(TEXT("ERROR: Failed to register file watcher"));
 185→    }
 186→#else
