 314→void UBridgeComponent::HandleReadyState(const TSharedPtr<FJsonObject>& JsonObj)
 315→{
 316→    // Support both flat and nested "ready" object
 317→    const TSharedPtr<FJsonObject>* ReadyObjPtr;
 318→    const TSharedPtr<FJsonObject>& ReadyData =
 319→        JsonObj->TryGetObjectField(TEXT("ready"), ReadyObjPtr) ? *ReadyObjPtr : JsonObj;
 320→
 321→    int32 TotalQuestions = ReadyData->GetIntegerField(TEXT("total_questions"));
 322→    FString FirstScene = ReadyData->GetStringField(TEXT("first_scene"));
 323→
 324→    BridgeLog(FString::Printf(TEXT("Claude Code ready! Total questions: %d, First scene: %s"),
 325→        TotalQuestions, *FirstScene));
 326→
 327→    bIsConnected = true;
 328→    OnBridgeReady.Broadcast(TotalQuestions);
