 716→
 717→FString UBridgeComponent::BuildQuestionJson()
 718→{
 719→    // Build JSON representation for backward-compatible delegates
 720→    TSharedPtr<FJsonObject> JsonObj = MakeShared<FJsonObject>();
 721→    JsonObj->SetStringField(TEXT("type"), TEXT("question"));
 722→    JsonObj->SetNumberField(TEXT("index"), CurrentQuestion.Index);
 723→    JsonObj->SetNumberField(TEXT("total"), CurrentQuestion.Total);
 724→    JsonObj->SetStringField(TEXT("id"), CurrentQuestion.QuestionId);
 725→    JsonObj->SetStringField(TEXT("text"), CurrentQuestion.Text);
 726→    JsonObj->SetStringField(TEXT("scene"), CurrentQuestion.Scene);
 727→
 728→    TArray<TSharedPtr<FJsonValue>> OptionsArray;
 729→    for (int32 i = 0; i < CurrentQuestion.OptionLabels.Num(); ++i)
 730→    {
 731→        TSharedPtr<FJsonObject> OptionObj = MakeShared<FJsonObject>();
 732→        OptionObj->SetNumberField(TEXT("index"), i);
 733→        OptionObj->SetStringField(TEXT("label"), CurrentQuestion.OptionLabels[i]);
 734→        OptionObj->SetStringField(TEXT("direction"), CurrentQuestion.OptionDirections[i]);
 735→        OptionsArray.Add(MakeShared<FJsonValueObject>(OptionObj));
 736→    }
 737→    JsonObj->SetArrayField(TEXT("options"), OptionsArray);
 738→
 739→    FString OutputString;
 740→    TSharedRef<TJsonWriter<>> Writer = TJsonWriterFactory<>::Create(&OutputString);
 741→    FJsonSerializer::Serialize(JsonObj.ToSharedRef(), Writer);
 742→    return OutputString;
 743→}
