1016→    }
1017→
1018→    FString Timestamp = FDateTime::UtcNow().ToIso8601();
1019→
1020→    // Update message_type to "ack"
1021→    Content = UpdateUsdaVariant(Content, TEXT("message_type"), TEXT("ack"));
1022→
