1026→    Content = UpdateUsdaAttribute(Content, TEXT("Ack"), TEXT("project"), TEXT("TranslatorsCard"), true);
1027→    Content = UpdateUsdaAttribute(Content, TEXT("Ack"), TEXT("timestamp"), Timestamp, true);
1028→
1029→    if (FFileHelper::SaveStringToFile(Content, *FilePath))
1030→    {
1031→        BridgeLog(TEXT("USD acknowledgment sent"));
1032→        bUsingUsdMode = true;
1033→    }
1034→    else
1035→    {
1036→        BridgeLog(TEXT("USD ack failed, sending JSON"));
1037→        SendAcknowledge();
1038→    }
