 15→
 16→FPerceptionEndpoint::FPerceptionEndpoint(UViewportPerceptionSubsystem* InSubsystem)
 17→	: Subsystem(InSubsystem)
 18→{
 19→}
 20→
 21→FPerceptionEndpoint::~FPerceptionEndpoint()
 22→{
 23→	Stop();
 24→}
 25→
 26→void FPerceptionEndpoint::Start()
 27→{
 28→	if (bRunning)
 29→	{
 30→		return;
 31→	}
 32→
 33→	FHttpServerModule& HttpModule = FHttpServerModule::Get();
 34→	TSharedPtr<IHttpRouter> Router = HttpModule.GetHttpRouter(PERCEPTION_PORT);
 35→
 36→	if (!Router.IsValid())
 37→	{
 38→		UE_LOG(LogViewportPerception, Warning, TEXT("Failed to get HTTP router on port %d"), PERCEPTION_PORT);
 39→		return;
 40→	}
 41→
 42→	// GET /perception/frame
 43→	RouteHandles.Add(Router->BindRoute(
 44→		FHttpPath(TEXT("/perception/frame")),
 45→		EHttpServerRequestVerbs::VERB_GET,
 46→		FHttpRequestHandler::CreateRaw(this, &FPerceptionEndpoint::HandleFrame)
 47→	));
 48→
 49→	// GET /perception/status
 50→	RouteHandles.Add(Router->BindRoute(
 51→		FHttpPath(TEXT("/perception/status")),
 52→		EHttpServerRequestVerbs::VERB_GET,
 53→		FHttpRequestHandler::CreateRaw(this, &FPerceptionEndpoint::HandleStatus)
 54→	));
 55→
 56→	// PUT /perception/config
 57→	RouteHandles.Add(Router->BindRoute(
 58→		FHttpPath(TEXT("/perception/config")),
 59→		EHttpServerRequestVerbs::VERB_PUT,
 60→		FHttpRequestHandler::CreateRaw(this, &FPerceptionEndpoint::HandleConfig)
 61→	));
 62→
 63→	// PUT /perception/start
 64→	RouteHandles.Add(Router->BindRoute(
 65→		FHttpPath(TEXT("/perception/start")),
 66→		EHttpServerRequestVerbs::VERB_PUT,
 67→		FHttpRequestHandler::CreateRaw(this, &FPerceptionEndpoint::HandleStart)
 68→	));
 69→
 70→	// PUT /perception/stop
 71→	RouteHandles.Add(Router->BindRoute(
 72→		FHttpPath(TEXT("/perception/stop")),
 73→		EHttpServerRequestVerbs::VERB_PUT,
 74→		FHttpRequestHandler::CreateRaw(this, &FPerceptionEndpoint::HandleStop)
 75→	));
 76→
 77→	// GET /perception/single
 78→	RouteHandles.Add(Router->BindRoute(
 79→		FHttpPath(TEXT("/perception/single")),
 80→		EHttpServerRequestVerbs::VERB_GET,
 81→		FHttpRequestHandler::CreateRaw(this, &FPerceptionEndpoint::HandleSingle)
 82→	));
 83→
 84→	// PUT /perception/single
 85→	RouteHandles.Add(Router->BindRoute(
 86→		FHttpPath(TEXT("/perception/single")),
 87→		EHttpServerRequestVerbs::VERB_PUT,
 88→		FHttpRequestHandler::CreateRaw(this, &FPerceptionEndpoint::HandleSingle)
 89→	));
 90→
 91→	HttpModule.StartAllListeners();
 92→	bRunning = true;
 93→
 94→	UE_LOG(LogViewportPerception, Log, TEXT("HTTP endpoint started on port %d"), PERCEPTION_PORT);
 95→}
 96→
 97→void FPerceptionEndpoint::Stop()
 98→{
 99→	if (!bRunning)
100→	{
101→		return;
102→	}
103→
104→	FHttpServerModule& HttpModule = FHttpServerModule::Get();
105→	TSharedPtr<IHttpRouter> Router = HttpModule.GetHttpRouter(PERCEPTION_PORT);
106→
107→	if (Router.IsValid())
108→	{
109→		for (const FHttpRouteHandle& Handle : RouteHandles)
110→		{
111→			Router->UnbindRoute(Handle);
112→		}
113→	}
114→
115→	RouteHandles.Empty();
116→	bRunning = false;
117→
118→	UE_LOG(LogViewportPerception, Log, TEXT("HTTP endpoint stopped"));
119→}
120→
121→bool FPerceptionEndpoint::HandleFrame(const FHttpServerRequest& Request,
122→                                       const FHttpResultCallback& OnComplete)
123→{
124→	if (!Subsystem)
125→	{
126→		SendJsonResponse(OnComplete, TEXT("{\"error\":\"Subsystem not available\"}"), 503);
127→		return true;
128→	}
129→
130→	FPerceptionPacket Packet = Subsystem->GetLatestPacket();
131→
132→	if (!Packet.bValid)
133→	{
134→		SendJsonResponse(OnComplete, TEXT("{\"error\":\"No frame available\"}"), 404);
135→		return true;
136→	}
137→
138→	// Build JSON response
139→	TSharedRef<FJsonObject> Root = MakeShared<FJsonObject>();
140→
141→	// Base64 encode the image
142→	FString ImageBase64 = FBase64::Encode(Packet.ImageData.GetData(), Packet.ImageData.Num());
143→	Root->SetStringField(TEXT("image"), ImageBase64);
144→	Root->SetNumberField(TEXT("width"), Packet.Width);
145→	Root->SetNumberField(TEXT("height"), Packet.Height);
146→	Root->SetStringField(TEXT("format"),
147→		Packet.Format == EPerceptionImageFormat::PNG ? TEXT("png") : TEXT("jpeg"));
148→	Root->SetNumberField(TEXT("frame_number"), static_cast<double>(Packet.FrameNumber));
149→	Root->SetNumberField(TEXT("timestamp"), Packet.Timestamp);
150→
151→	// Camera
152→	TSharedRef<FJsonObject> CameraObj = MakeShared<FJsonObject>();
153→	TArray<TSharedPtr<FJsonValue>> LocArr;
154→	LocArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.Camera.Location.X));
155→	LocArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.Camera.Location.Y));
156→	LocArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.Camera.Location.Z));
157→	CameraObj->SetArrayField(TEXT("location"), LocArr);
158→
159→	TArray<TSharedPtr<FJsonValue>> RotArr;
160→	RotArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.Camera.Rotation.Pitch));
161→	RotArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.Camera.Rotation.Yaw));
162→	RotArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.Camera.Rotation.Roll));
163→	CameraObj->SetArrayField(TEXT("rotation"), RotArr);
164→	CameraObj->SetNumberField(TEXT("fov"), Packet.Metadata.Camera.FOV);
165→	Root->SetObjectField(TEXT("camera"), CameraObj);
166→
167→	// Viewport
168→	TSharedRef<FJsonObject> ViewportObj = MakeShared<FJsonObject>();
169→	TArray<TSharedPtr<FJsonValue>> SizeArr;
170→	SizeArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.ViewportSize.X));
171→	SizeArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.ViewportSize.Y));
172→	ViewportObj->SetArrayField(TEXT("size"), SizeArr);
173→	ViewportObj->SetStringField(TEXT("type"), Packet.Metadata.ViewportType);
174→	Root->SetObjectField(TEXT("viewport"), ViewportObj);
175→
176→	// Selection
177→	TArray<TSharedPtr<FJsonValue>> SelArr;
178→	for (const FString& Name : Packet.Metadata.SelectedActors)
179→	{
180→		SelArr.Add(MakeShared<FJsonValueString>(Name));
181→	}
182→	Root->SetArrayField(TEXT("selection"), SelArr);
183→
184→	// Scene
185→	TSharedRef<FJsonObject> SceneObj = MakeShared<FJsonObject>();
186→	SceneObj->SetStringField(TEXT("map"), Packet.Metadata.MapName);
187→	SceneObj->SetNumberField(TEXT("actor_count"), Packet.Metadata.ActorCount);
188→	Root->SetObjectField(TEXT("scene"), SceneObj);
189→
190→	// Timing
191→	TSharedRef<FJsonObject> TimingObj = MakeShared<FJsonObject>();
192→	TimingObj->SetNumberField(TEXT("delta_time"), Packet.Metadata.DeltaTime);
193→	TimingObj->SetNumberField(TEXT("fps"), Packet.Metadata.FPS);
194→	Root->SetObjectField(TEXT("timing"), TimingObj);
195→
196→	// Serialize
197→	FString JsonBody;
198→	TSharedRef<TJsonWriter<>> Writer = TJsonWriterFactory<>::Create(&JsonBody);
199→	FJsonSerializer::Serialize(Root, Writer);
200→
201→	SendJsonResponse(OnComplete, JsonBody);
202→	return true;
203→}
204→
205→bool FPerceptionEndpoint::HandleStatus(const FHttpServerRequest& Request,
206→                                        const FHttpResultCallback& OnComplete)
207→{
208→	TSharedRef<FJsonObject> Root = MakeShared<FJsonObject>();
209→
210→	Root->SetBoolField(TEXT("capturing"), Subsystem ? Subsystem->IsCapturing() : false);
211→	Root->SetBoolField(TEXT("has_new_frame"), Subsystem ? Subsystem->HasNewFrame() : false);
212→	Root->SetNumberField(TEXT("port"), PERCEPTION_PORT);
213→	Root->SetBoolField(TEXT("running"), bRunning);
214→
215→	FString JsonBody;
216→	TSharedRef<TJsonWriter<>> Writer = TJsonWriterFactory<>::Create(&JsonBody);
217→	FJsonSerializer::Serialize(Root, Writer);
218→
219→	SendJsonResponse(OnComplete, JsonBody);
220→	return true;
221→}
222→
223→bool FPerceptionEndpoint::HandleConfig(const FHttpServerRequest& Request,
224→                                        const FHttpResultCallback& OnComplete)
225→{
226→	if (!Subsystem)
227→	{
228→		SendJsonResponse(OnComplete, TEXT("{\"error\":\"Subsystem not available\"}"), 503);
229→		return true;
230→	}
231→
232→	// Parse request body as JSON
233→	if (Request.Body.Num() == 0)
234→	{
235→		SendJsonResponse(OnComplete, TEXT("{\"status\":\"no changes\"}"));
236→		return true;
237→	}
238→
239→	FString BodyStr = UTF8_TO_TCHAR(reinterpret_cast<const char*>(Request.Body.GetData()));
240→	TSharedRef<TJsonReader<>> Reader = TJsonReaderFactory<>::Create(BodyStr);
241→	TSharedPtr<FJsonObject> Body;
242→
243→	if (FJsonSerializer::Deserialize(Reader, Body) && Body.IsValid())
244→	{
245→		double MaxFPS;
246→		if (Body->TryGetNumberField(TEXT("max_fps"), MaxFPS))
247→		{
248→			Subsystem->SetMaxCaptureRate(static_cast<float>(MaxFPS));
249→		}
250→
251→		int32 Width = 0, Height = 0;
252→		if (Body->TryGetNumberField(TEXT("width"), Width) &&
253→		    Body->TryGetNumberField(TEXT("height"), Height))
254→		{
255→			Subsystem->SetCaptureResolution(Width, Height);
256→		}
257→
258→		FString Format;
259→		if (Body->TryGetStringField(TEXT("format"), Format))
260→		{
261→			Subsystem->SetImageFormat(
262→				Format.Equals(TEXT("png"), ESearchCase::IgnoreCase)
263→					? EPerceptionImageFormat::PNG
264→					: EPerceptionImageFormat::JPEG
265→			);
266→		}
267→
268→		int32 Quality;
269→		if (Body->TryGetNumberField(TEXT("quality"), Quality))
270→		{
271→			Subsystem->SetJPEGQuality(Quality);
272→		}
273→	}
274→
275→	SendJsonResponse(OnComplete, TEXT("{\"status\":\"configured\"}"));
276→	return true;
277→}
278→
279→bool FPerceptionEndpoint::HandleStart(const FHttpServerRequest& Request,
280→                                       const FHttpResultCallback& OnComplete)
281→{
282→	if (!Subsystem)
283→	{
284→		SendJsonResponse(OnComplete, TEXT("{\"error\":\"Subsystem not available\"}"), 503);
285→		return true;
286→	}
287→
288→	// Parse optional params from body (defaults used if body is empty)
289→	float FPS = 5.0f;
290→	int32 Width = 1280, Height = 720;
291→
292→	if (Request.Body.Num() > 0)
293→	{
294→		FString BodyStr = UTF8_TO_TCHAR(reinterpret_cast<const char*>(Request.Body.GetData()));
295→		TSharedRef<TJsonReader<>> Reader = TJsonReaderFactory<>::Create(BodyStr);
296→		TSharedPtr<FJsonObject> Body;
297→
298→		if (FJsonSerializer::Deserialize(Reader, Body) && Body.IsValid())
299→		{
300→			double V;
301→			if (Body->TryGetNumberField(TEXT("fps"), V)) FPS = static_cast<float>(V);
302→			Body->TryGetNumberField(TEXT("width"), Width);
303→			Body->TryGetNumberField(TEXT("height"), Height);
304→		}
305→	}
306→
307→	Subsystem->StartCapture(FPS, Width, Height);
308→	SendJsonResponse(OnComplete, TEXT("{\"status\":\"capturing\"}"));
309→	return true;
310→}
311→
312→bool FPerceptionEndpoint::HandleStop(const FHttpServerRequest& Request,
313→                                      const FHttpResultCallback& OnComplete)
314→{
315→	if (Subsystem)
316→	{
317→		Subsystem->StopCapture();
318→	}
319→
320→	SendJsonResponse(OnComplete, TEXT("{\"status\":\"stopped\"}"));
321→	return true;
322→}
323→
324→bool FPerceptionEndpoint::HandleSingle(const FHttpServerRequest& Request,
325→                                        const FHttpResultCallback& OnComplete)
326→{
327→	if (!Subsystem)
328→	{
329→		SendJsonResponse(OnComplete, TEXT("{\"error\":\"Subsystem not available\"}"), 503);
330→		return true;
331→	}
332→
333→	// If not capturing, start a temporary capture
334→	const bool WasCapturing = Subsystem->IsCapturing();
335→	if (!WasCapturing)
336→	{
337→		Subsystem->RequestSingleFrame();
338→	}
339→
340→	// Give the frame a moment to arrive, then try to read
341→	// We schedule a delayed response via async
342→	AsyncTask(ENamedThreads::GameThread, [this, OnComplete, WasCapturing]()
343→	{
344→		if (!Subsystem)
345→		{
346→			SendJsonResponse(OnComplete, TEXT("{\"error\":\"Subsystem destroyed\"}"), 500);
347→			return;
348→		}
349→
350→		// Try to get a frame with a brief spin (up to 500ms)
351→		FPerceptionPacket Packet;
352→		constexpr float MaxWait = 0.5f;
353→		constexpr float PollInterval = 0.05f;
354→		float Waited = 0.0f;
355→
356→		while (Waited < MaxWait)
357→		{
358→			Packet = Subsystem->GetLatestPacket();
359→			if (Packet.bValid)
360→			{
361→				break;
362→			}
363→			FPlatformProcess::Sleep(PollInterval);
364→			Waited += PollInterval;
