 89→		return Result;
 90→	}
 91→
 92→	// Set raw pixel data
 93→	const TArray<uint8>* RawData = reinterpret_cast<const TArray<uint8>*>(&Pixels);
 94→	if (ImageWrapper->SetRaw(
 95→		Pixels.GetData(),
 96→		Pixels.Num() * sizeof(FColor),
 97→		Size.X,
 98→		Size.Y,
 99→		ERGBFormat::BGRA,
100→		8))
101→	{
102→		// Compress
103→		const int32 CompressQuality = (Format == EPerceptionImageFormat::JPEG) ? FMath::Clamp(Quality, 1, 100) : 0;
104→		Result = ImageWrapper->GetCompressed(CompressQuality);
105→	}
106→	else
107→	{
108→		UE_LOG(LogViewportPerception, Warning, TEXT("Failed to set raw image data for encoding"));
109→	}
110→
111→	return Result;
