import unreal

# Check what Motion Design / text-related actors and plugins are available
# List actors related to text, motion design, or UI
actors = unreal.EditorActorSubsystem().get_all_level_actors()

text_actors = []
motion_actors = []
for a in actors:
    class_name = a.get_class().get_name()
    label = a.get_actor_label()
    if any(kw in class_name.lower() for kw in ["text", "font", "motion", "cloner", "effector"]):
        text_actors.append((label, class_name))
    if any(kw in label.lower() for kw in ["text", "title", "label", "hud"]):
        motion_actors.append((label, class_name))

print("Text/Motion related actors:")
for label, cls in text_actors + motion_actors:
    print(f"  {label} ({cls})")

if not text_actors and not motion_actors:
    print("  None found yet")

# Check available Motion Design actor classes
print("\nAvailable Motion Design classes:")
for cls_name in ["TextRenderActor", "Text3DActor", "ClonerActor", "EffectorActor", 
                  "MotionDesignTextActor", "AvaText3DActor", "AvaRundownPagePlayer"]:
    try:
        cls = unreal.find_class(cls_name)
        if cls:
            print(f"  {cls_name}: available")
    except:
        pass

# Check Avalanche (Motion Design) plugin status
print("\nChecking Motion Design/Avalanche plugin...")
try:
    # Avalanche is the internal name for Motion Design
    result = unreal.SystemLibrary.get_platform_user_name()
    print(f"Editor responding (user: {result})")
except:
    pass

