import unreal

eas = unreal.EditorActorSubsystem()
actors = eas.get_all_level_actors()
text_actor = None
for a in actors:
    if 'CRT_Text' in a.get_actor_label():
        text_actor = a
        break

if text_actor:
    # Check Text3D component details
    comps = text_actor.get_components_by_class(unreal.ActorComponent)
    for c in comps:
        cname = c.get_class().get_name()
        if 'Text3D' in cname or 'AvaText' in cname:
            # Try to get bounding box of the text
            print(f"Component: {c.get_name()} ({cname})")
            # Get text properties
            try:
                print(f"  has_text: {c.get_text()}")
            except:
                pass
            try:
                print(f"  font_size: {c.get_editor_property('font_size')}")
            except:
                pass
            try:
                print(f"  extrude: {c.get_editor_property('extrude')}")
            except:
                pass

    # Get bounds
    origin, extent = text_actor.get_actor_bounds(False)
    print(f"\nBounds origin: ({origin.x:.1f}, {origin.y:.1f}, {origin.z:.1f})")
    print(f"Bounds extent: ({extent.x:.1f}, {extent.y:.1f}, {extent.z:.1f})")
    print(f"Approximate width: {extent.x * 2:.1f}")
    print(f"Approximate height: {extent.z * 2:.1f}")
else:
    print("CRT_Text not found")

