import unreal

# Stop piloting
try:
    unreal.EditorLevelLibrary.eject_pilot_level_actor()
    print("Ejected from piloting")
except:
    print("Eject not available")

eas = unreal.EditorActorSubsystem()
actors = eas.get_all_level_actors()
text_actor = None
for a in actors:
    if 'CRT_Text' in a.get_actor_label():
        text_actor = a
        break

if text_actor:
    # Get the Text3D component
    text_comp = None
    for c in text_actor.get_components_by_class(unreal.ActorComponent):
        if 'Text3D' in c.get_class().get_name() or 'AvaText' in c.get_class().get_name():
            text_comp = c
            break

    if text_comp:
        # Check available methods for setting text
        # AvaText3DComponent likely uses set_text or set_editor_property('text', ...)
        try:
            current = text_comp.get_editor_property('text')
            print(f"Current text: '{current}'")
        except Exception as e:
            print(f"Get text error: {e}")

        # Try setting via editor property
        try:
            text_comp.set_editor_property('text', 'HELLO')
            print("Set text='HELLO' via editor property")
        except Exception as e:
            print(f"Set text error: {e}")

        # Check font size
        try:
            fs = text_comp.get_editor_property('font_size')
            print(f"Font size: {fs}")
        except:
            pass
    else:
        print("No Text3D component found")

