eas = unreal.EditorActorSubsystem()
actors = eas.get_all_level_actors()
text_actor = None
for a in actors:
    if 'CRT_Text' in a.get_actor_label():
        text_actor = a
        break

if text_actor:
    # Check character meshes for valid geometry
    comps = text_actor.get_components_by_class(unreal.StaticMeshComponent)
    for c in comps:
        mesh = c.get_editor_property('static_mesh')
        if mesh:
            bounds = mesh.get_bounds()
            verts = mesh.get_num_lod_vertices(0) if hasattr(mesh, 'get_num_lod_vertices') else -1
            print(f"{c.get_name()}: mesh={mesh.get_name()}, verts={verts}")
            # Get relative location  
            rel_loc = c.get_editor_property('relative_location')
            print(f"  rel_loc=({rel_loc.x:.1f}, {rel_loc.y:.1f}, {rel_loc.z:.1f})")
        else:
            print(f"{c.get_name()}: NO MESH")

    # Try forcing text regeneration
    text_comp = None
    for c in text_actor.get_components_by_class(unreal.ActorComponent):
        if 'Text3D' in c.get_class().get_name() or 'AvaText' in c.get_class().get_name():
            text_comp = c
            break

    if text_comp:
        # List available methods
        methods = [m for m in dir(text_comp) if 'generat' in m.lower() or 'rebuild' in m.lower() or 'refresh' in m.lower() or 'update' in m.lower()]
        print(f"\nText3D methods (generate/rebuild/refresh/update): {methods}")

        # Try calling generate
        for m in methods:
            if callable(getattr(text_comp, m, None)):
                try:
                    getattr(text_comp, m)()
                    print(f"Called {m}()")
                except Exception as e:
                    print(f"  {m}() failed: {e}")

