eas = unreal.EditorActorSubsystem()
cloner = None
for a in eas.get_all_level_actors():
    if a.get_actor_label() == 'CRT_DotGrid':
        cloner = a
        break

# List ALL components including child components
all_comps = cloner.get_components_by_class(unreal.ActorComponent)
for c in all_comps:
    cn = c.get_class().get_name()
    print(f"  {c.get_name()} ({cn})")
    if hasattr(c, 'is_active'):
        try:
            print(f"    active: {c.is_active()}")
        except:
            pass
    if hasattr(c, 'is_visible'):
        try:
            print(f"    visible: {c.is_visible()}")
        except:
            pass

# Try to find Niagara component specifically
niag = cloner.get_component_by_class(unreal.NiagaraComponent)
if niag:
    print(f"\nNiagaraComponent found: active={niag.is_active()}")
    # Try activating
    niag.activate(True)
    niag.set_active(True)
    print(f"After activate: active={niag.is_active()}")
else:
    print("\nNo NiagaraComponent found on cloner")

# Check the CEClonerComponent methods for activation
comp = all_comps[0]
activate_methods = [m for m in dir(comp) if any(k in m.lower() for k in ['activ', 'enabl', 'start', 'render', 'spawn'])]
print(f"\nActivation methods: {activate_methods}")

